/**
 * Framework control catalog.
 *
 * The seeded library of controls per compliance framework, plus the curated
 * crosswalk between them. This file is the source of truth for the content;
 * the migration `prisma/migrations/*_framework_control_catalog` inserts the
 * same rows (generated by `npx tsx scripts/gen-framework-catalog-sql.ts`),
 * and `syncFrameworkCatalog()` upserts them for the demo seeder.
 *
 * Codes are the stable identity within a framework and must never change once
 * shipped — ComplianceMapping rows reference the catalog row by id, and the
 * migration's ON CONFLICT (framework, code) DO NOTHING relies on codes staying
 * put. Edit titles/descriptions freely; add new controls at the end of a
 * category with a fresh sortOrder.
 *
 * Content notes:
 * - NIST AI RMF 1.0 is represented at the category level (GOVERN 1..6,
 *   MAP 1..5, MEASURE 1..4, MANAGE 1..4). Subcategories are too granular for
 *   a per-system attestation and map many-to-one onto these anyway.
 * - ISO/IEC 42001:2023 uses the Annex A control identifiers.
 * - EU AI Act (Regulation (EU) 2024/1689) is represented by the articles that
 *   carry concrete provider/deployer obligations. Applicability depends on the
 *   system's risk tier; the classification wizard narrows the list.
 * - SOC 2 uses the 2017 Trust Services Criteria (CC1–CC9, A1, C1, PI1, P1–P8).
 */

import type { ComplianceFramework } from "@prisma/client";

export type CatalogFramework = Exclude<ComplianceFramework, "CUSTOM">;

export type CatalogControl = {
  framework: CatalogFramework;
  code: string;
  title: string;
  description: string;
  category: string;
  sortOrder: number;
};

export type CatalogCrosswalk = {
  from: { framework: CatalogFramework; code: string };
  to: { framework: CatalogFramework; code: string };
  note?: string;
};

export const FRAMEWORK_LABELS: Record<ComplianceFramework, string> = {
  EU_AI_ACT: "EU AI Act",
  NIST_AI_RMF: "NIST AI RMF",
  ISO_42001: "ISO/IEC 42001",
  SOC2: "SOC 2",
  CUSTOM: "Custom",
};

export const FRAMEWORK_DESCRIPTIONS: Record<CatalogFramework, string> = {
  NIST_AI_RMF:
    "Voluntary US framework organised around four functions — Govern, Map, Measure, Manage — for managing risks to individuals, organisations and society from AI.",
  ISO_42001:
    "Certifiable AI management system standard. Annex A lists the controls an organisation implements to govern the responsible development and use of AI.",
  EU_AI_ACT:
    "Binding EU regulation with tiered obligations. Prohibited practices apply from February 2025, GPAI obligations from August 2025, and most high-risk requirements from August 2026.",
  SOC2:
    "AICPA Trust Services Criteria used for third-party assurance reports on security, availability, processing integrity, confidentiality and privacy.",
};

export const CATALOG_FRAMEWORKS: CatalogFramework[] = [
  "EU_AI_ACT",
  "NIST_AI_RMF",
  "ISO_42001",
  "SOC2",
];

export function isCatalogFramework(value: string): value is CatalogFramework {
  return (CATALOG_FRAMEWORKS as string[]).includes(value);
}

