export const FRAMEWORK_CROSSWALK: CatalogCrosswalk[] = XW.flatMap(([fw, code, targets]) =>
  targets.map(([toFw, toCode]) => ({ from: { framework: fw, code }, to: { framework: toFw, code: toCode } }))
);

/** Stable lookup key for a control: `${framework}::${code}`. */
export function controlKey(framework: string, code: string): string {
  return `${framework}::${code}`;
}

/**
 * Validates the catalog's internal consistency. Throws if a crosswalk points
 * at a control that does not exist or links a framework to itself. Runs in
 * tests and in the SQL generator so a typo cannot ship as a silently-missing
 * row.
 */
export function assertCatalogIntegrity(): void {
  const keys = new Set(FRAMEWORK_CATALOG.map((c) => controlKey(c.framework, c.code)));
  if (keys.size !== FRAMEWORK_CATALOG.length) {
    throw new Error("Framework catalog has duplicate (framework, code) entries");
  }
  const seenPairs = new Set<string>();
  for (const xw of FRAMEWORK_CROSSWALK) {
    const a = controlKey(xw.from.framework, xw.from.code);
    const b = controlKey(xw.to.framework, xw.to.code);
    if (!keys.has(a)) throw new Error(`Crosswalk references unknown control ${a}`);
    if (!keys.has(b)) throw new Error(`Crosswalk references unknown control ${b}`);
    if (xw.from.framework === xw.to.framework) {
      throw new Error(`Crosswalk links ${a} within its own framework`);
    }
    const pair = [a, b].sort().join("<->");
    if (seenPairs.has(pair)) throw new Error(`Duplicate crosswalk pair ${pair}`);
    seenPairs.add(pair);
  }
}

// ─── Runtime sync (seeder / dev) ───────────────────────────────────────────

type CatalogClient = {
  frameworkControl: {
    upsert: (args: {
      where: { framework_code: { framework: ComplianceFramework; code: string } };
      update: { title: string; description: string; category: string; sortOrder: number };
      create: {
        framework: ComplianceFramework;
        code: string;
        title: string;
        description: string;
        category: string;
        sortOrder: number;
        builtIn: boolean;
      };
      select: { id: true };
    }) => Promise<{ id: string }>;
  };
  controlCrosswalk: {
    upsert: (args: {
      where: { fromControlId_toControlId: { fromControlId: string; toControlId: string } };
      update: Record<string, never>;
      create: { fromControlId: string; toControlId: string; note?: string };
    }) => Promise<unknown>;
  };
};

/**
 * Idempotently upserts the built-in catalog and crosswalk. Used by the demo
 * seeder; production relies on the migration. Returns a map of control key ->
 * id so callers can create mappings against the catalog.
 */
export async function syncFrameworkCatalog(db: CatalogClient): Promise<Map<string, string>> {
  assertCatalogIntegrity();
  const ids = new Map<string, string>();
  for (const control of FRAMEWORK_CATALOG) {
    const row = await db.frameworkControl.upsert({
      where: { framework_code: { framework: control.framework, code: control.code } },
      update: {
        title: control.title,
        description: control.description,
        category: control.category,
        sortOrder: control.sortOrder,
      },
      create: { ...control, builtIn: true },
      select: { id: true },
    });
    ids.set(controlKey(control.framework, control.code), row.id);
  }
  for (const xw of FRAMEWORK_CROSSWALK) {
    const fromControlId = ids.get(controlKey(xw.from.framework, xw.from.code))!;
    const toControlId = ids.get(controlKey(xw.to.framework, xw.to.code))!;
    await db.controlCrosswalk.upsert({
      where: { fromControlId_toControlId: { fromControlId, toControlId } },
      update: {},
      create: { fromControlId, toControlId, note: xw.note },
    });
  }
  return ids;
}
